<?php require_once __DIR__ . '/ResourceController.php'; final class UserController { public static function index(string $method, ?string $id = null): never { if ($method === 'GET' && $id === null) ResourceController::list('users', ['Super Admin']); if ($method === 'GET') ResourceController::show('users', $id, ['Super Admin']); if ($method === 'POST' && $id === null) ResourceController::collection('users', ['Super Admin'], 201); if ($method === 'PUT') ResourceController::update('users', $id, ['Super Admin']); if ($method === 'DELETE') ResourceController::delete('users', $id); Response::error('Method not allowed', 'METHOD_NOT_ALLOWED', 405); } }
